from openpyxl import load_workbook
wb = load_workbook('input/monthly_operations_template.xlsx', data_only=True)
print('Sheets:', wb.sheetnames)
for s in ['Hourly_Summary','Daily_Summary','Zone_Summary','Payment_Summary','Fare_Distance_Bands','Reconciliation']:
    ws = wb[s]
    print(f'\n=== {s} === rows={ws.max_row} cols={ws.max_column}')
    for r in range(1, min(ws.max_row+1, 45)):
        row_vals = []
        for c in range(1, min(ws.max_column+1, 10)):
            cell = ws.cell(row=r, column=c)
            v = cell.value
            if v is not None:
                row_vals.append(f'{cell.coordinate}={v}')
        if row_vals:
            print(f'  Row {r}: {\" | \".join(row_vals[:8])}')
# Also check formula versions for key cells
wb2 = load_workbook('input/monthly_operations_template.xlsx', data_only=False)
for s in ['Hourly_Summary','Daily_Summary','Payment_Summary','Reconciliation']:
    ws = wb2[s]
    print(f'\n=== {s} (formulas) ===')
    for r in range(1, min(ws.max_row+1, 45)):
        for c in range(1, min(ws.max_column+1, 10)):
            cell = ws.cell(row=r, column=c)
            if cell.value and isinstance(cell.value, str) and cell.value.startswith('='):
                print(f'  {cell.coordinate}={cell.value}')
wb.close()
wb2.close()
" 2>&1 | head -300

